SOURCES = {"~": "message", "≈": "inferred"}


def when(value):
    """«DD.MM HH:MM» (или «~…» — по времени сообщения, «≈…» — выведено из контекста) → (ISO, точное?, источник)."""
    if not value:
        return None, False, ""
    src = SOURCES.get(value[0], "text")
    exact = src == "text"
    day, hm = value.lstrip("~≈").split()
    d, m = map(int, day.split("."))
    h, mi = map(int, hm.split(":"))
    return datetime(YEAR, m, d, h, mi, tzinfo=TZ).isoformat(), exact, src


def build():
    ops, seen = [], set()
    for msgs, product, operation, start, end, people, qty, unit, plan, note, flag in R:
        ids = msgs.split(",")
        key = f"tg-{ids[0]}-{len([o for o in ops if o['msgs'][0] == ids[0]])}"
        assert key not in seen
        seen.add(key)
        start_at, start_exact, start_src = when(start)
        end_at, end_exact, end_src = when(end)
        if start_at and end_at:
            assert end_at >= start_at, (msgs, start, end)
        ops.append({
            "id": key, "msgs": ids, "product": product, "operation": operation, "people": people,
            "qty": qty, "unit": unit, "plan": plan, "start_at": start_at, "start_exact": start_exact,
            "end_at": end_at, "end_exact": end_exact, "start_src": start_src, "end_src": end_src,
            "status": "closed" if end_at else "open",
            "flag": flag or "ok", "note": note,
        })
    handoffs = []
    for product, at, qty, msgs in HANDOFFS:
        iso, exact, _ = when(at)
        handoffs.append({"product": product, "at": iso, "exact": exact, "qty": qty, "unit": "шт", "msgs": msgs.split(",")})
    return {"source": CHAT, "parsed_by": "разбор по сменам с перепроверкой, номера сообщений в msgs",
            "operations": ops, "handoffs": handoffs}


if __name__ == "__main__":
    data = build()
    OUT.write_text(json.dumps(data, ensure_ascii=False, indent=0), encoding="utf-8")
    ops = data["operations"]
    print(f"{OUT.name}: операций {len(ops)}, с концом {sum(1 for o in ops if o['end_at'])}, "
          f"check {sum(1 for o in ops if o['flag'] == 'check')}, invalid {sum(1 for o in ops if o['flag'] == 'invalid')}, "
          f"передач на фасовку {len(data['handoffs'])}")
